    vector<pair<int,int>> edges(N-1);
    for (int i = 0; i < N-1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
        edges[i] = {a, b};
    }

    string S;
    cin >> S;
    int total = 0;
    vector<int> val(N);
    for (int i = 0; i < N; i++) {
        val[i] = S[i] - '0';
        total += val[i];
    }

    if (total == 0) {
        cout << 0 << "\n";
        return 0;
    }

    // DFS to compute subtree sums
    vector<int> sub(N, 0);
    function<void(int,int)> dfs = [&](int u, int p) {
        sub[u] = val[u];
        for (int v : g[u]) {
            if (v == p) continue;
            dfs(v, u);
            sub[u] += sub[v];
        }
    };
    dfs(0, -1);

    long long moves = 0;
    bool possible = true;
    for (auto [a, b] : edges) {
