        adj[b].push_back(a);
    }
    string s; cin >> s;

    // BFS from each vertex - O(N^2), hopefully N is small
    // Find sum of distances from each vertex to all pieces
    vector<long long> sumDist(n+1, 0);
    vector<int> col(n+1, -1);
    // BFS from vertex 1 to get colors
    // For parity: color vertices 0/1 in bipartite manner
    // pieces_on_color0 mod 2 must equal 0 or total mod 2

    int total = count(s.begin(), s.end(), '1');

    for(int src=1;src<=n;src++){
        vector<int> dist(n+1,-1);
        queue<int> q;
        dist[src]=0; q.push(src);
        while(!q.empty()){
            int u=q.front();q.pop();
            for(int v:adj[u]) if(dist[v]==-1){dist[v]=dist[u]+1;q.push(v);}
        }
        for(int i=1;i<=n;i++) if(s[i-1]=='1') sumDist[src]+=dist[i];
    }

    // Color
    col[1]=0; queue<int> q; q.push(1);
    while(!q.empty()){int u=q.front();q.pop();for(int v:adj[u])if(col[v]==-1){col[v]=1-col[u];q.push(v);}}
    int pc0=0; for(int i=1;i<=n;i++) if(s[i-1]=='1'&&col[i]==0) pc0++;

    long long ans = LLONG_MAX;
    for(int v=1;v<=n;v++){
        int need = (col[v]==0)?total:0;
        if(pc0%2 == need%2) ans=min(ans,sumDist[v]/2);
    }
    if(ans==LLONG_MAX) cout<<"Impossible"<<endl;
    else cout<<ans<<endl;
}

