using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    string S;
    cin >> S;

    vector<int> pieces;
    for (int i = 0; i < N; i++) {
        if (S[i] == '1') pieces.push_back(i);
    }

    int K = (int)pieces.size();
    if (K <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    // Build parent/depth/order from an arbitrary root.
    int root = 0;
    vector<int> parent(N, -1), depth(N, 0), order;
    order.reserve(N);
    queue<int> q;
    q.push(root);
    parent[root] = root;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        order.push_back(v);
        for (int to : g[v]) {
            if (parent[to] != -1) continue;
            parent[to] = v;
            depth[to] = depth[v] + 1;
            q.push(to);
        }
    }

    // cnt[v] = number of pieces in subtree of v (with this rooting)
    vector<int> cnt(N, 0);
    for (int v : pieces) cnt[v] = 1;
    for (int i = N - 1; i > 0; i--) {
        int v = order[i];
        cnt[parent[v]] += cnt[v];
    }

    // Necessary and sufficient condition:
    // For every edge, both sides cannot have odd number of pieces.
    // Since total K must be odd for gathering to one vertex.
    if (K % 2 == 0) {
        cout << -1 << '\n';
        return 0;
    }
    for (int v = 1; v < N; v++) {
        if (cnt[v] % 2 == 1) {
            cout << -1 << '\n';
            return 0;
        }
    }

    // If possible, minimum moves = sum over edges of cnt_side / 2,
    // where cnt_side is the number of pieces in the child side.
    ll ans = 0;
    for (int v = 1; v < N; v++) {
        ans += cnt[v] / 2;
    }

    cout << ans << '\n';
    return 0;
}

