int piece_count[MAXN];
long long dist_sum[MAXN];
int total_pieces;
int parent[MAXN];

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void dfs_count(int u, int p) {
    parent[u] = p;
    piece_count[u] = (s[u] == '1');
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == p) continue;
        dfs_count(v, u);
        piece_count[u] += piece_count[v];
    }
}

void dfs_dist(int u, int p, long long depth) {
    dist_sum[u] = depth;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == p) continue;
        dfs_dist(v, u, depth + 1);
    }
}

int find_centroid(int u, int p) {
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v != p && piece_count[v] > total_pieces / 2)
            return find_centroid(v, u);
    }
    return u;
}

