#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static int N;
static Edge *edges;
static int *head;
static int ecnt = 0;
static char *S;

static int *parent_arr;
static int *order;
static int *subcnt;
static ll *downCost;
static ll *sumDist;

static void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;

    head = (int *)malloc((N + 1) * sizeof(int));
    edges = (Edge *)malloc((2 * (N - 1)) * sizeof(Edge));
    parent_arr = (int *)malloc((N + 1) * sizeof(int));
    order = (int *)malloc(N * sizeof(int));
    subcnt = (int *)malloc((N + 1) * sizeof(int));
    downCost = (ll *)malloc((N + 1) * sizeof(ll));
    sumDist = (ll *)malloc((N + 1) * sizeof(ll));

    for (int i = 1; i <= N; i++) head[i] = -1;

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        add_edge(a, b);
        add_edge(b, a);
    }

    S = (char *)malloc((N + 5) * sizeof(char));
    scanf("%s", S + 1);

    int totalPieces = 0;
    for (int i = 1; i <= N; i++) totalPieces += (S[i] == '1');

    if (totalPieces == 0) {
        printf("Yes\n0\n");
        return 0;
    }

    /* Build parent and traversal order iteratively */
    int front = 0, back = 0;
    order[back++] = 1;
    parent_arr[1] = 0;

    while (front < back) {
        int v = order[front++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            parent_arr[to] = v;
            order[back++] = to;
        }
    }

    /* Postorder DP:
       subcnt[v] = number of pieces in subtree
       downCost[v] = sum of distances from v to all pieces in subtree
    */
    for (int i = 1; i <= N; i++) {
        subcnt[i] = (S[i] == '1') ? 1 : 0;
        downCost[i] = 0;
    }

    for (int i = N - 1; i > 0; i--) {
        int v = order[i];
        int p = parent_arr[v];
        subcnt[p] += subcnt[v];
        downCost[p] += downCost[v] + (ll)subcnt[v];
    }

    /* Reroot to get sumDist[v] = sum of distances from v to all pieces */
    sumDist[1] = downCost[1];
    for (int i = 0; i < N; i++) {
        int v = order[i];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent_arr[v]) continue;
            sumDist[to] = sumDist[v] + (ll)totalPieces - 2LL * subcnt[to];
        }
    }

    /* Feasibility:
       Let d_i be distance from chosen center to each piece.
       One move decreases total distance by 2, so answer would be sumDist[c]/2.
       This is possible iff no piece starts at distance 1 from center.
       Equivalently, every initial piece must be at even positive distance or already at center.
       On a tree, that means all pieces lie on same bipartition side as center.
       So feasible iff all piece vertices have same parity in any rooting.
    */
    int parity = -1;
    int depthParityOk = 1;
    int *depth = (int *)malloc((N + 1) * sizeof(int));
    depth[1] = 0;
    for (int i = 1; i < N; i++) {
        int v = order[i];
        depth[v] = depth[parent_arr[v]] ^ 1;
    }

    for (int i = 1; i <= N; i++) {
        if (S[i] == '1') {
            if (parity == -1) parity = depth[i] & 1;
            else if (((depth[i] & 1) != parity)) {
                depthParityOk = 0;
                break;
            }
        }
    }

    if (!depthParityOk) {
        printf("No\n");
        return 0;
    }

    ll best = -1;
    for (int v = 1; v <= N; v++) {
        if ((depth[v] & 1) == parity) {
            ll moves = sumDist[v] / 2;
            if (best == -1 || moves < best) best = moves;
        }
    }

    printf("Yes\n%lld\n", best);

    free(depth);
    free(sumDist);
    free(downCost);
    free(subcnt);
    free(order);
    free(parent_arr);
    free(S);
    free(edges);
    free(head);
    return 0;
}

