        int cnt = (pieces[u] == '1') ? 1 : 0;
        for (int v : tree[u]) {
            if (v != parent) {
                int sub = dfs(v, u);
                moves += Math.min(sub, totalPieces - sub);
                cnt += sub;
            }
        }
