/*
Key fact:
A move chooses two pieces whose distance is at least 2, and moves both by 1 along the unique path between them.
So each move reduces the sum of distances to the final gathering vertex by exactly 2.

For a chosen gathering vertex r:
- Let cnt = number of pieces.
- Let distSum = sum of distances from every piece to r.
Necessary lower bound on moves = distSum / 2.
This is achievable iff for every connected component of T - {r}, the number of pieces inside it
does not exceed the number of pieces outside it:
    2 * pieces_in_component <= cnt
because pieces in that component must be paired with pieces outside while moving across edge to r.

Thus r is feasible iff the maximum number of pieces in any component after removing r is at most cnt/2.

For a neighbor v of r:
- if v is a child in some rooted tree, that component has piece count sub[v]
- if v is the parent, that component has piece count total - sub[r]

We compute:
1) total pieces
2) subtree piece counts
3) for every vertex, the maximum component piece count after removing it
4) among feasible vertices, minimum distSum/2

distSum for all roots is computed by reroot DP:
distSum[child] = distSum[parent] + total - 2 * sub[child]

If total <= 1, answer is 0.
If no feasible vertex exists, answer is -1.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        int[] head = new int[N];
        Arrays.fill(head, -1);
        int[] to = new int[2 * Math.max(0, N - 1)];
        int[] next = new int[2 * Math.max(0, N - 1)];
        int edgeCnt = 0;

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            to[edgeCnt] = b;
            next[edgeCnt] = head[a];
            head[a] = edgeCnt++;

            to[edgeCnt] = a;
            next[edgeCnt] = head[b];
            head[b] = edgeCnt++;
        }

        String S = fs.next();
        int[] piece = new int[N];
        long total = 0;
        for (int i = 0; i < N; i++) {
            piece[i] = S.charAt(i) - '0';
            total += piece[i];
        }

        if (total <= 1) {
            System.out.println(0);
            return;
        }

        int[] parent = new int[N];
        Arrays.fill(parent, -1);
        int[] order = new int[N];
        int ordSz = 0;

        int[] stack = new int[N];
        int sp = 0;
        stack[sp++] = 0;
        parent[0] = -2;

        while (sp > 0) {
            int u = stack[--sp];
            order[ordSz++] = u;
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[sp++] = v;
            }
        }
        parent[0] = -1;

        long[] sub = new long[N];
        long dist0 = 0;
        int[] depth = new int[N];
        for (int i = 0; i < ordSz; i++) {
            int u = order[i];
            if (parent[u] != -1) depth[u] = depth[parent[u]] + 1;
            dist0 += (long) depth[u] * piece[u];
        }

        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];
            sub[u] += piece[u];
            if (parent[u] != -1) sub[parent[u]] += sub[u];
        }

        long[] dist = new long[N];
        dist[0] = dist0;
        for (int i = 0; i < ordSz; i++) {
            int u = order[i];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                dist[v] = dist[u] + total - 2L * sub[v];
            }
        }

        long ans = Long.MAX_VALUE;

        for (int u = 0; u < N; u++) {
            long maxComp = total - sub[u]; // parent side
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                if (sub[v] > maxComp) maxComp = sub[v];
            }
            if (2L * maxComp <= total) {
                ans = Math.min(ans, dist[u] / 2L);
            }
        }

        System.out.println(ans == Long.MAX_VALUE ? -1 : ans);
    }
}

import sys
sys.setrecursionlimit(300000)

def solve():
    N = int(sys.stdin.readline())
    edges = [[] for _ in range(N)]
    for _ in range(N - 1):
        a, b = map(int, sys.stdin.readline().split())
        a -= 1
        b -= 1
        edges[a].append(b)
        edges[b].append(a)
    S = sys.stdin.readline().strip()
    pieces = [int(c) for c in S]
    total_pieces = sum(pieces)

    if total_pieces % 2 == 1:
        print(-1)
        return

    # First DFS to compute subtree piece counts and total distance from root (0)
    parent = [-1]*N
    order = [0]
    for v in order:
        for u in edges[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    sub_pieces = pieces[:]
    for v in reversed(order):
        for u in edges[v]:
            if u != parent[v]:
                sub_pieces[v] += sub_pieces[u]

    # Check feasibility: for some root, no subtree > total_pieces/2
    feasible = False
    for v in range(N):
        ok = True
        for u in edges[v]:
            if u == parent[v]:
                if total_pieces - sub_pieces[v] > total_pieces // 2:
                    ok = False
                    break
            else:
                if sub_pieces[u] > total_pieces // 2:
                    ok = False
                    break
        if ok:
            feasible = True
            break

    if not feasible:
        print(-1)
        return

    # Compute total distance from root 0
    depth = [0]*N
    for v in order:
        for u in edges[v]:
            if u != parent[v]:
                depth[u] = depth[v] + 1
    total_dist_root = sum(depth[v] * pieces[v] for v in range(N))

    # Reroot DP to get total distance for all vertices
    dist = [0]*N
    dist[0] = total_dist_root
    for v in order:
        for u in edges[v]:
            if u != parent[v]:
                dist[u] = dist[v] - sub_pieces[u] + (total_pieces - sub_pieces[u])

    min_dist = min(dist)
    print(min_dist // 2)

if __name__ == "__main__":
    solve()
